INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('ds',0,'STACKS','Which structure follows Last-In, First-Out (LIFO)?',NULL,'["Stack","Queue","Array","Binary tree"]'::jsonb,0,'Think of a pile of plates.','A stack removes the item added most recently. A queue is First-In, First-Out.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('ds',1,'QUEUES','Which structure follows First-In, First-Out (FIFO)?',NULL,'["Queue","Stack","Heap","Hash map"]'::jsonb,0,'Like people waiting in line.','A queue serves items in the order they arrived.',false) ON CONFLICT (topic_id,position) DO NOTHING;
