INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('net',0,'OSI MODEL','How many layers does the OSI model have?',NULL,'["7", "4", "5", "9"]'::jsonb,0,'Physical is layer 1 and Application is the top.','The OSI model has 7 layers. The TCP/IP model has 4.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('net',1,'IP ADDRESSING','Which of these is a PRIVATE IPv4 address?',NULL,'["192.168.1.10", "8.8.8.8", "172.32.0.1", "11.0.0.1"]'::jsonb,0,'Private ranges: 10.x.x.x, 172.16-31.x.x and 192.168.x.x.','192.168.0.0/16 is private. 172.32.0.1 is outside the 172.16.0.0-172.31.255.255 range, so it is public.',true) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('net',2,'SUBNETTING','How many usable host addresses does a /24 network have?',NULL,'["254", "256", "255", "252"]'::jsonb,0,'Two addresses are reserved.','A /24 has 256 addresses. The network and broadcast addresses are reserved, leaving 254 usable hosts.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('net',3,'PROTOCOLS','Which protocol turns a domain name into an IP address?',NULL,'["DNS", "DHCP", "ARP", "FTP"]'::jsonb,0,'It is the phone book of the internet.','DNS resolves names like example.com to IP addresses. DHCP hands out IP addresses.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('net',4,'DEVICES','Which device forwards traffic BETWEEN different networks?',NULL,'["Router", "Hub", "Repeater", "Switch"]'::jsonb,0,'It makes routing decisions using IP addresses.','A router connects networks and chooses paths with IP addresses. A switch connects devices inside one network.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('net',5,'TCP VS UDP','Which protocol is connectionless?',NULL,'["UDP", "TCP", "HTTP", "SSH"]'::jsonb,0,'Video calls prefer speed over guaranteed delivery.','UDP sends datagrams without a handshake or retransmission. TCP sets up a connection and guarantees order.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_topics (id,title,subtitle,category,level,file_name,lang_badge,position) VALUES ('sec','Cyber Security','CIA triad, crypto, passwords & common attacks (IT 416)','security','Intermediate','security.txt','SEC',9) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('sec',0,'CIA TRIAD','In the CIA triad, what does the "C" stand for?',NULL,'["Confidentiality", "Control", "Compliance", "Cryptography"]'::jsonb,0,'It is about keeping data secret from the wrong people.','The CIA triad is Confidentiality, Integrity and Availability.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('sec',1,'ATTACKS','A fake email that tricks you into entering your password is called...',NULL,'["Phishing", "Sniffing", "Fuzzing", "Patching"]'::jsonb,0,'The word sounds like fishing.','Phishing uses fake messages or sites to steal credentials.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('sec',2,'CRYPTOGRAPHY','Which of these is a SYMMETRIC encryption algorithm?',NULL,'["AES", "RSA", "ECC", "Diffie-Hellman"]'::jsonb,0,'Symmetric means one shared key for both encrypting and decrypting.','AES uses the same key to encrypt and decrypt. RSA and ECC are asymmetric (public/private key pairs).',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('sec',3,'PASSWORDS','How should a server store user passwords?',NULL,'["As salted hashes", "In plain text", "Encrypted with the key stored next to them", "Encoded with Base64"]'::jsonb,0,'A good method cannot be reversed.','Salted, slow hashes (bcrypt, Argon2) cannot be reversed. Base64 is only encoding, not protection.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('sec',4,'SQL INJECTION','What is the best defense against SQL injection?',NULL,'["Parameterized queries", "Longer table names", "Hiding the login page", "Using GET instead of POST"]'::jsonb,0,'Keep user input separate from the SQL command.','Parameterized queries send the SQL and the data separately, so input can never change the query.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('sec',5,'AUTHENTICATION','What does multi-factor authentication (MFA) add?',NULL,'["A second proof of identity", "A longer password", "Faster login", "A VPN"]'::jsonb,0,'A password alone is only one factor.','MFA asks for something more than a password, such as a code from your phone.',false) ON CONFLICT (topic_id,position) DO NOTHING;
