INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('math',0,'BINARY','What is the binary number 1010 in decimal?',NULL,'["10", "12", "8", "5"]'::jsonb,0,'From the left: 8 + 0 + 2 + 0.','1010 = 1x8 + 0x4 + 1x2 + 0x1 = 10.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('math',1,'HEXADECIMAL','What is decimal 255 in hexadecimal?',NULL,'["FF", "EE", "F0", "1F"]'::jsonb,0,'The largest value of one byte.','255 = 15x16 + 15, and 15 is F, so it is FF.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('math',2,'LOGIC','What is the result of True AND False?',NULL,'["False", "True", "Null", "Both"]'::jsonb,0,'AND needs both sides to be true.','AND is true only when both inputs are true.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('math',3,'SETS','If A = {1, 2, 3} and B = {3, 4}, what is A ∩ B?',NULL,'["{3}", "{1, 2, 3, 4}", "{1, 2}", "{4}"]'::jsonb,0,'The intersection is what both sets share.','The intersection contains only elements found in both sets: {3}.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('math',4,'DE MORGAN','NOT (A AND B) is equal to...',NULL,'["(NOT A) OR (NOT B)", "(NOT A) AND (NOT B)", "A OR B", "NOT A AND B"]'::jsonb,0,'Negating AND turns it into OR.','De Morgan: NOT(A AND B) = (NOT A) OR (NOT B).',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('math',5,'FUNCTIONS','If f(x) = 2x + 3, what is f(4)?',NULL,'["11", "8", "14", "9"]'::jsonb,0,'Replace x with 4.','f(4) = 2x4 + 3 = 11.',false) ON CONFLICT (topic_id,position) DO NOTHING;
